      '.swal-modal .swal-button--confirm',
      '.modal.show .btn-confirm',
      '.modal.show [data-confirm="true"]',
      '.modal.show button.btn-primary',
      '[role="dialog"][aria-modal="true"] .confirm',
      '[role="dialog"][aria-modal="true"] [data-confirm]',
